import React from 'react';
import { Doughnut } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { DomainStatus } from '../types';
import ProgressChart from './ProgressChart';

ChartJS.register(ArcElement, Tooltip, Legend);

interface SidebarProps {
  statuses: DomainStatus[];
  overallScore: number;
  domainProgress: {
    current: number;
    total: number;
    estimate: number;
  };
}

const getProficiencyLabel = (score: number): string => {
  if (score >= 75) return 'Olgun';
  if (score >= 40) return 'Gelişmekte';
  return 'Temel';
};

const Sidebar: React.FC<SidebarProps> = ({ statuses, overallScore, domainProgress }) => {
  const getStatusDotColor = (status: DomainStatus['status']) => ({
    'Complete': 'bg-green-500',
    'In Progress': 'bg-blue-500', 
    'Pending': 'bg-gray-500',
  }[status]);

  const currentDomain = statuses.find(s => s.status === 'In Progress');

  return (
    <aside className="hidden lg:flex w-full lg:w-[400px] bg-[#1e1e3f] flex-col border-t lg:border-t-0 lg:border-l border-[#2d2d5f] overflow-y-auto">
      <div className="p-6 border-b border-[#2d2d5f]">
        <h2 className="text-base font-semibold text-gray-100 mb-4">Değerlendirme İlerlemesi</h2>
        <div className="flex flex-col items-center gap-4">
          <div className="w-[180px] h-[180px]">
            <ProgressChart statuses={statuses} />
          </div>
          <div className="text-center -mt-2">
            <div className="text-4xl font-bold text-blue-400">{overallScore.toFixed(1)}</div>
            <div className="text-sm text-gray-400 mt-1">Genel Olgunluk Skoru</div>
          </div>
        </div>
      </div>
      
      {currentDomain && (
        <div className="p-6 border-b border-[#2d2d5f] bg-black/10">
          <h2 className="text-base font-semibold text-gray-100 mb-3">Aktif Alan: {currentDomain.name}</h2>
          <div className="bg-[#0f172a] border border-[#334155] rounded-lg p-4 space-y-3">
            <div>
                <div className="flex justify-between items-center mb-1">
                    <span className="text-sm font-medium text-gray-300">Alan Skoru</span>
                    <span className="text-sm font-semibold text-blue-400">{currentDomain.score.toFixed(1)}%</span>
                </div>
                <div className="flex-1 h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-blue-500 to-cyan-400" style={{ width: `${currentDomain.score}%` }}></div>
                </div>
            </div>
            {/* GÜNCELLENMİŞ GÖSTERGE: Yeni sayaç mantığı burada kullanılıyor */}
            <div className='border-t border-gray-700/50 pt-3 text-center text-xs text-gray-400 flex justify-around'>
                {domainProgress.total > 0 && (
                    <span>Değerlendirme Adımı: <strong>{domainProgress.current} / {domainProgress.total}</strong></span>
                )}
                <span>|</span>
                <span>Kalan Süre: <strong>~{domainProgress.estimate} dk</strong></span>
            </div>
          </div>
        </div>
      )}

      <div className="p-6">
        <h2 className="text-base font-semibold text-gray-100 mb-4">Alan Durumları</h2>
        <div className="flex flex-col gap-3">
          {statuses.map((domain) => (
            <div key={domain.name} className={`flex items-center gap-3 p-3 rounded-md transition-all
              ${domain.status === 'In Progress' 
                ? 'bg-blue-500/10 border border-blue-500/50 shadow-lg' 
                : 'bg-[#0f172a]/50 border border-transparent'}`
            }>
              <div className={`w-2.5 h-2.5 rounded-full ${getStatusDotColor(domain.status)} flex-shrink-0`}></div>
              <div className="flex-1">
                <span className="text-sm text-gray-200 font-medium truncate">{domain.name}</span>
              </div>
              <div className="text-xs font-semibold">
                {domain.status === 'Complete' && (
                  <span className='text-green-400'>{getProficiencyLabel(domain.score)}</span>
                )}
                {domain.status === 'In Progress' && (
                  <span className='text-blue-400'>Devam Ediyor</span>
                )}
                 {domain.status === 'Pending' && (
                  <span className='text-gray-500'>Bekliyor</span>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;
